  const p = Nav.actual().params; p.color = el.dataset.c; if (dato('notas', p.id)) cambiar('notas', p.id, { color: el.dataset.c });
  $$('[data-a="notaColor"]').forEach(b => b.classList.toggle('on', b === el));
